const root = document.querySelector('#pageRoot');
const crumb = document.querySelector('#crumb');
const navItems = [...document.querySelectorAll('.nav-item')];
const toast = document.querySelector('#toast');
const state = { page: 'dashboard', display: 'fila', queued: [], seen: new Set(), generated: '' };
const pageNames = {dashboard:'Painel',postagem:'Gerar postagem',ofertas:'Ofertas e cupons',modelos:'Modelos de mensagem',fila:'Modo Fila',lista:'Modo Lista',copiador:'Copiador',agendamentos:'Agendamentos',canais:'WhatsApp e Telegram',stories:'Stories e redes',biolink:'Bio link',relatorios:'Relatórios',integracoes:'Integrações'};
const demoOffers=[{name:'Fone Bluetooth com estojo',store:'Shopee · demonstração',price:'R$ 89,90',old:'R$ 149,90',icon:'♫'},{name:'Cafeteira compacta',store:'Amazon · demonstração',price:'R$ 129,00',old:'R$ 189,00',icon:'◉'},{name:'Mochila urbana impermeável',store:'Mercado Livre · demonstração',price:'R$ 74,90',old:'R$ 119,90',icon:'◇'}];
function showToast(text){toast.textContent=text;toast.classList.add('show');clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>toast.classList.remove('show'),2400)}
function heading(title,description,action=''){return `<div class="page-heading"><div><p class="eyebrow">Área de demonstração</p><h1>${title}</h1><p>${description}</p></div>${action?`<div class="heading-actions">${action}</div>`:''}</div>`}
function card(title,description,body,badge=''){return `<article class="card"><div class="card-header"><div><h2>${title}</h2>${description?`<p>${description}</p>`:''}</div>${badge?`<span class="label-pill ${badge==='DADOS FICTÍCIOS'?'sample':''}">${badge}</span>`:''}</div>${body}</article>`}
function stats(){return `<div class="stats-grid"><article class="stat-card"><div class="stat-top">Rascunhos locais <span class="stat-icon">✎</span></div><strong>${state.queued.length+1}</strong><small><b>+1</b> sessão demonstrativa</small></article><article class="stat-card"><div class="stat-top">Canais conectados <span class="stat-icon">◉</span></div><strong>0</strong><small>Conexões externas desligadas</small></article><article class="stat-card"><div class="stat-top">Ofertas de exemplo <span class="stat-icon">◇</span></div><strong>03</strong><small>Dados sintéticos da interface</small></article><article class="stat-card"><div class="stat-top">Envios realizados <span class="stat-icon">↗</span></div><strong>0</strong><small>Nenhuma publicação executada</small></article></div>`}
function offerRows(){return demoOffers.map(o=>`<div class="offer-row"><div class="product-thumb">${o.icon}</div><div><h3>${o.name}</h3><p>${o.store}</p></div><div class="offer-price">${o.price}<del>${o.old}</del></div></div>`).join('')}
function dashboard(){return `${heading('Painel','Visão geral dos fluxos observáveis, com amostras locais claramente identificadas.','<button class="btn primary" data-go="postagem">＋ Nova postagem</button>')}${stats()}<div class="panel-grid">${card('Atividade recente','Eventos apenas desta sessão de demonstração.',`<div class="activity"><div><strong>Rascunho criado localmente</strong><small>Gerador · agora</small></div><span class="value">1 item</span><span class="status-pill ready">LOCAL</span></div><div class="activity"><div><strong>Conexão de canal</strong><small>WhatsApp / Telegram</small></div><span class="value">—</span><span class="status-pill off">OFFLINE</span></div><div class="activity"><div><strong>Último envio</strong><small>Operações externas bloqueadas</small></div><span class="value">—</span><span class="status-pill off">NENHUM</span></div>`)}${card('Saúde das integrações','Conectividade e autorização são estados distintos.',`<div class="integration-row"><span class="integration-logo">WA</span><div><strong>WhatsApp</strong><small>Não configurado nesta demonstração</small></div><span class="status-pill off">Desconectado</span></div><div class="integration-row"><span class="integration-logo">TG</span><div><strong>Telegram</strong><small>Não configurado nesta demonstração</small></div><span class="status-pill off">Desconectado</span></div><div class="integration-row"><span class="integration-logo">API</span><div><strong>Marketplaces</strong><small>Sem credenciais ou consulta em rede</small></div><span class="status-pill off">Desconectado</span></div>`)}</div>${card('Ofertas de demonstração','Produtos inventados para testar layout e navegação.',`<div class="offer-list">${offerRows()}</div>`,'DADOS FICTÍCIOS')}`}
function postagem(){return `${heading('Gerar postagem','Preencha dados de exemplo para montar um rascunho. Este protótipo não busca o produto no link.')}${card('Dados do produto','A conversão de URLs reais depende de APIs oficiais e credenciais autorizadas.',`<form id="postForm"><div class="form-grid"><div class="field full"><label for="productUrl">Link do produto (opcional no modo manual)</label><input id="productUrl" type="url" placeholder="https://loja.example/produto" autocomplete="url"><span class="field-help">Links não são consultados nem enviados a nenhum servidor.</span></div><div class="field full"><label for="productName">Nome do produto</label><input id="productName" required maxlength="120" placeholder="Ex.: Fone Bluetooth"></div><div class="field"><label for="price">Preço atual</label><input id="price" inputmode="decimal" placeholder="89,90"></div><div class="field"><label for="oldPrice">Preço anterior (opcional)</label><input id="oldPrice" inputmode="decimal" placeholder="149,90"></div><div class="field"><label for="store">Loja</label><select id="store"><option>Shopee (demonstração)</option><option>Amazon (demonstração)</option><option>Mercado Livre (demonstração)</option><option>Magalu (demonstração)</option><option>SHEIN (demonstração)</option></select></div><div class="field"><label for="coupon">Cupom (opcional)</label><input id="coupon" maxlength="32" placeholder="EXEMPLO"></div><div class="field full"><label for="hook">Gancho personalizado</label><input id="hook" maxlength="120" placeholder="Oferta de demonstração"></div></div><div class="form-footer"><button class="btn primary" type="submit">Gerar rascunho</button><span class="field-help">Geração local; nenhuma postagem será enviada.</span></div></form><div id="postResult" aria-live="polite"></div>`)}`}
function ofertas(){return `${heading('Ofertas e cupons','Catálogo visual de amostra. Preços e cupons não foram verificados em lojas.')}${card('Ofertas de exemplo','Filtro local por título ou marketplace.',`<div class="toolbar"><input class="search-box" id="offerSearch" placeholder="Buscar oferta ou loja…" aria-label="Buscar ofertas"><span class="label-pill sample">DADOS FICTÍCIOS</span></div><div class="offer-list" id="offerList">${offerRows()}</div><div class="empty-search" id="emptySearch">Nenhuma amostra corresponde ao filtro.</div>`)}`}
function modelos(){return `${heading('Modelos de mensagem','Edite um template local e visualize o texto. A amostra não é enviada.')}${card('Template por loja','Placeholders locais: {produto}, {preco}, {cupom}.',`<form id="templateForm"><div class="field"><label for="templateText">Texto do modelo</label><textarea id="templateText" maxlength="500">✨ {produto}\n🔥 Por {preco}\n🏷️ Cupom: {cupom}\n🔗 Link de demonstração</textarea></div><div class="form-footer"><button class="btn primary" type="submit">Salvar neste navegador</button><button class="btn" type="button" id="previewTemplate">Pré-visualizar</button></div><div id="templateResult" class="result-box" hidden></div></form>`)}`}
function queuePage(mode){const isList=mode==='lista';const rows=state.queued.length?state.queued.map((x,i)=>`<div class="activity"><div><strong>${x.name}</strong><small>${x.store} · rascunho ${i+1}</small></div><span class="value">${x.price||'Preço pendente'}</span><button class="btn small danger" data-remove="${i}">Remover</button></div>`).join(''):`<div class="empty-state"><strong>Sem itens nesta sessão</strong>Adicione um rascunho local para visualizar ${isList?'o modo lista':'a fila'}.</div>`;return `${heading(isList?'Modo Lista':'Modo Fila',isList?'Organize rascunhos em uma lista editável.':'Revise uma sequência de rascunhos antes de agendar.')}${card(isList?'Lista de publicação':'Fila de publicação',isList?'Amostras podem ser reordenadas no protótipo.':'Intervalos de envio são apenas parâmetros de demonstração.',`<div class="toolbar"><div class="toggle-group"><button data-display="fila" aria-pressed="${!isList}">Fila</button><button data-display="lista" aria-pressed="${isList}">Lista</button></div><button class="btn primary" data-go="postagem">＋ Adicionar rascunho</button></div>${rows}<div class="form-footer" style="margin-top:14px"><label class="field" style="max-width:210px;margin:0">Intervalo (minutos)<input type="number" min="1" max="1440" value="30" aria-label="Intervalo de demonstração"></label><button class="btn" id="scheduleDemo">Agendar localmente</button></div><p class="field-help">Agendamento externo desativado; clicar apenas registra a intenção na interface.</p>`)}`}
function copier(){return `${heading('Copiador','Área para estudar entrada, revisão e deduplicação sem monitorar grupos ou acessar mensagens.')}${card('Prévia manual de texto','Cole um exemplo sintético para extrair campos de forma local.',`<form id="copyForm"><div class="field"><label for="copyInput">Texto sintético da oferta</label><textarea id="copyInput" placeholder="Produto de demonstração — R$ 49,90 — https://example.com/item/123"></textarea><span class="field-help">Não cole mensagens privadas ou dados reais de grupos.</span></div><div class="form-footer"><button class="btn primary" type="submit">Analisar texto</button><span class="label-pill">SEM GRUPOS CONECTADOS</span></div></form><div id="copyResult" aria-live="polite"></div>`)}${card('Regras observáveis','Em produção, cópia automática exige origem autorizada, API permitida, aprovação e deduplicação persistente.',`<div class="activity"><div><strong>Normalizar link</strong><small>Na demonstração, mantém a URL sem alterar afiliados</small></div><span class="status-pill off">OFFLINE</span></div><div class="activity"><div><strong>Deduplicação</strong><small>Hash apenas em memória durante esta sessão</small></div><span class="status-pill warn">VOLÁTIL</span></div><div class="activity"><div><strong>Publicação</strong><small>Não implementada neste protótipo</small></div><span class="status-pill off">BLOQUEADA</span></div>`)}`}
function agendamentos(){const rows=state.queued.length?state.queued.map((x,i)=>`<div class="activity"><div><strong>${x.name}</strong><small>Horário ainda não definido · sessão atual</small></div><span class="status-pill warn">RASCUNHO</span><button class="btn small" data-remove="${i}">Cancelar</button></div>`).join(''):`<div class="empty-state"><strong>Nenhum agendamento</strong>Gere uma postagem e use “Agendar localmente” para ver um item neste protótipo.</div>`;return `${heading('Agendamentos','Rascunhos programados localmente; nenhum job persistente ou envio ativo.')}${card('Calendário de demonstração','Não há conexão com scheduler.',`${rows}<div style="margin-top:12px"><button class="btn" data-go="postagem">Criar rascunho</button></div>`)}`}
function canais(){return `${heading('WhatsApp e Telegram','Gerencie destinos e canais somente após configurar integrações oficiais e consentimento.')}${card('Canais disponíveis','Estado real de autenticação não pode ser validado aqui.',`<div class="connection-card"><div><h3>WhatsApp</h3><p>Nenhuma instância conectada. O protótipo não exibe QR, não lê contatos e não envia mensagens.</p></div><span class="status-pill off">Desconectado</span></div><div class="connection-card"><div><h3>Telegram</h3><p>Bot não configurado. Nenhum token solicitado ou armazenado.</p></div><span class="status-pill off">Desconectado</span></div><div class="form-footer"><button class="btn" disabled title="Integração não existe neste protótipo">Testar conectividade</button><span class="field-help">Ação desabilitada: sem credenciais de teste autorizadas.</span></div>`)}`}
function stories(){return `${heading('Stories e redes','Composição de exemplo em formato vertical. Imagem externa e publicação não estão conectadas.')}${card('Prévia vertical 9:16','Layout fictício para ilustrar uma peça social.',`<div class="story-preview" role="img" aria-label="Prévia de Story fictício"><span class="label-pill sample">DEMO</span><div class="story-photo">◇</div><strong>Oferta de exemplo</strong><small>Preço ilustrativo · link fictício</small></div><div class="form-footer" style="justify-content:center;margin-top:14px"><button class="btn" id="downloadStory">Salvar ficha de prévia</button><span class="field-help">Nenhum arquivo de imagem real foi gerado.</span></div>`)}`}
function biolink(){return `${heading('Bio link','Vitrine local com produtos inventados; não há URL pública nem métricas de visitantes.')}${card('Prévia de vitrine','Os botões são exemplos e não levam a uma loja real.',`<div class="bio-preview"><div class="bio-avatar">RO</div><h3>Radar de Ofertas</h3><p>Seleção demonstrativa de ofertas</p><a class="bio-link" href="#ofertas" data-go="ofertas">Fone Bluetooth · amostra</a><a class="bio-link" href="#ofertas" data-go="ofertas">Cafeteira compacta · amostra</a><a class="bio-link" href="#ofertas" data-go="ofertas">Mochila urbana · amostra</a></div>`)}`}
function relatorios(){return `${heading('Relatórios','Amostras sintéticas para exibir dimensões comuns de analytics. Não são comissões reais.')}${stats()}${card('Resumo da demonstração','Janela: sessão atual · tamanho da amostra: 3 produtos fictícios.',`<div class="table-wrap"><table><thead><tr><th>Indicador</th><th>Valor</th><th>Origem</th></tr></thead><tbody><tr><td><strong>Cliques</strong></td><td>0</td><td>Sem pixel/conexão</td></tr><tr><td><strong>Comissões</strong></td><td>—</td><td>Requer relatório oficial do afiliado</td></tr><tr><td><strong>Produtos exibidos</strong></td><td>3</td><td>Fixtures locais fictícias</td></tr></tbody></table></div>`,'DADOS FICTÍCIOS')}`}
function integracoes(){return `${heading('Integrações','Saúde separada por conectividade, autenticação e operação funcional.')}${card('Conectores','Nenhuma credencial é necessária ou armazenada para este protótipo.',`<div class="table-wrap"><table><thead><tr><th>Provedor</th><th>Conectividade</th><th>Autenticação</th><th>Operação</th><th>Última verificação</th></tr></thead><tbody>${['Shopee Open Platform','Amazon Creators API','Mercado Livre API','Magalu','SHEIN','WhatsApp Business','Telegram Bot API'].map(n=>`<tr><td><strong>${n}</strong></td><td><span class="status-pill off">Não testada</span></td><td><span class="status-pill off">Sem credencial</span></td><td><span class="status-pill off">Indisponível</span></td><td>—</td></tr>`).join('')}</tbody></table></div><p class="field-help">Os nomes indicam dependências possíveis; não afirmam que exista integração funcional neste protótipo.</p>`)}`}
const renderers={dashboard,postagem,ofertas,modelos,fila:()=>queuePage('fila'),lista:()=>queuePage('lista'),copiador:copier,agendamentos,canais,stories,biolink,relatorios,integracoes};
function render(page=state.page){state.page=renderers[page]?page:'dashboard';crumb.textContent=pageNames[state.page];navItems.forEach(b=>{b.classList.toggle('active',b.dataset.page===state.page);b.setAttribute('aria-current',b.dataset.page===state.page?'page':'false')});root.innerHTML=renderers[state.page]();if(state.page==='modelos'){const saved=localStorage.getItem('investigationTemplate');if(saved)document.querySelector('#templateText').value=saved}document.querySelector('#sidebar').classList.remove('open');document.querySelector('#menuToggle').setAttribute('aria-expanded','false');}
function go(page){if(!pageNames[page])return;location.hash=page;render(page)}
function safeUrl(value){if(!value)return '';try{const u=new URL(value);return ['http:','https:'].includes(u.protocol)?u.toString():''}catch{return ''}}
document.addEventListener('click',e=>{const nav=e.target.closest('[data-page]');if(nav)go(nav.dataset.page);const goBtn=e.target.closest('[data-go]');if(goBtn){e.preventDefault();go(goBtn.dataset.go)}const disp=e.target.closest('[data-display]');if(disp)go(disp.dataset.display);const remove=e.target.closest('[data-remove]');if(remove){state.queued.splice(Number(remove.dataset.remove),1);render();showToast('Rascunho removido desta sessão.')}if(e.target.closest('.notice-close'))e.target.closest('.notice').remove();if(e.target.closest('#menuToggle')){const open=document.querySelector('#sidebar').classList.toggle('open');e.target.closest('#menuToggle').setAttribute('aria-expanded',String(open))}if(e.target.closest('#previewTemplate')){const t=document.querySelector('#templateText').value;const out=document.querySelector('#templateResult');out.hidden=false;out.textContent=t.replaceAll('{produto}','Produto de demonstração').replaceAll('{preco}','R$ 89,90').replaceAll('{cupom}','EXEMPLO')}if(e.target.closest('#scheduleDemo')){if(!state.queued.length){showToast('Adicione um rascunho antes de agendar.');return}go('agendamentos');showToast('Intenção de agendamento registrada só na interface.')}if(e.target.closest('#downloadStory'))showToast('Prévia ilustrativa; nenhum arquivo de imagem foi criado.')});
document.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='postForm'){const name=document.querySelector('#productName').value.trim();const price=document.querySelector('#price').value.trim();const old=document.querySelector('#oldPrice').value.trim();const coupon=document.querySelector('#coupon').value.trim();const hook=document.querySelector('#hook').value.trim();const url=safeUrl(document.querySelector('#productUrl').value.trim());if(document.querySelector('#productUrl').value&&!url){showToast('Informe uma URL HTTP ou HTTPS válida.');return}const store=document.querySelector('#store').value;state.generated=[hook||'Oferta de demonstração',name,price?`Por R$ ${price}`:'Preço não informado',old?`Antes: R$ ${old}`:'',coupon?`Cupom: ${coupon}`:'',url||'Link não informado'].filter(Boolean).join('\n');state.queued.push({name,price:price?`R$ ${price}`:'',store});document.querySelector('#postResult').className='result-box';document.querySelector('#postResult').textContent=state.generated+'\n\nRASCUNHO LOCAL — não publicado.';showToast('Rascunho de demonstração criado.')}if(e.target.id==='templateForm'){localStorage.setItem('investigationTemplate',document.querySelector('#templateText').value);showToast('Modelo salvo neste navegador.')}if(e.target.id==='copyForm'){const raw=document.querySelector('#copyInput').value.trim();const urlMatch=raw.match(/https?:\/\/[^\s]+/i);const url=urlMatch?safeUrl(urlMatch[0]):'';const key=(url||raw).toLowerCase();const duplicate=state.seen.has(key);state.seen.add(key);document.querySelector('#copyResult').className='result-box';document.querySelector('#copyResult').textContent=`${duplicate?'DUPLICATA NESTA SESSÃO':'AMOSTRA NOVA'}\nURL detectada: ${url||'nenhuma URL HTTP(S)'}\n\nSem consulta, conversão de afiliado, grupo ou envio.`;showToast(duplicate?'Amostra repetida nesta sessão.':'Texto analisado localmente.')}});
document.addEventListener('input',e=>{if(e.target.id==='offerSearch'){const q=e.target.value.toLowerCase();let visible=0;document.querySelectorAll('#offerList .offer-row').forEach(row=>{const ok=row.textContent.toLowerCase().includes(q);row.hidden=!ok;if(ok)visible++});document.querySelector('#emptySearch').style.display=visible?'none':'block'}});
window.addEventListener('hashchange',()=>render(location.hash.slice(1)||'dashboard'));
const saved=localStorage.getItem('investigationTemplate');document.addEventListener('DOMContentLoaded',()=>{if(saved&&document.querySelector('#templateText'))document.querySelector('#templateText').value=saved});
render(location.hash.slice(1)||'dashboard');
